public class ListStackTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        SimpleStack st = new ListStack();
        check("new stack isEmpty()", true, st.isEmpty());
        check("pop() on empty stack", null, st.pop());

        st.push("a");
        st.push("b");
        st.push("c");
        check("isEmpty() after pushes", false, st.isEmpty());
        check("first pop is last push", "c", st.pop());
        check("second pop", "b", st.pop());

        st.push("d");
        check("pop after interleaved push", "d", st.pop());
        check("final pop", "a", st.pop());
        check("isEmpty() after popping everything", true, st.isEmpty());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

